void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    int i, unlocked = 0;

    /* Phase 1: Isolate pages by checking if they are memory locked */
    for (i = 0; i < pvec->nr; i++) {
        struct page *page = pvec->pages[i];

        if (PageLocked(page)) {
            unlock_page(page);
            unlocked++;
        }
    }

    /* Phase 2: Release reference pins on pages not being unlocked */
    for (i = 0; i < pvec->nr; i++) {
        struct page *page = pvec->pages[i];

        if (!PageLocked(page)) {
            put_page(page);
        }
    }

    /* Phase 3: Handle the putback of pages for fast path */
    spin_lock(&zone->lock);
    for (i = 0; i < pvec->nr; i++) {
        struct page *page = pvec->pages[i];

        if (PageLocked(page)) {
            __free_page(page);
        } else {
            page->flags &= ~PG_locked;
        }
    }
    spin_unlock(&zone->lock);

    pvec->nr = 0;
}

void pagevec_release_memory_locks(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i;

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = &pvec->pages[i];
        if (PageLocked(page)) {
            ClearPageLocked(page);
            unlock_page(page);
        }
    }

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = &pvec->pages[i];
        if (!PageLocked(page)) {
            pagevec_relesase_ref(pin_page(page));
        }
    }

    for (i = 0; i < pagevec_count(pvec); i++) {
        page = &pvec->pages[i];
        if (page_is_fastpath_eligible(page)) {
            putback_page(zone, page);
        }
    }

    pagevec_reinit(pvec);
}

