void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    int i;
    struct page *page;

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            ClearPageLocked(page);
            zone->locked_count--;
        }
    }

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        if (!PageLocked(page)) {
            page->ref_count--;
        }
    }

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        if (!PageLocked(page) && page->ref_count == 0) {
            put_page(page);
        }
    }
